ideTime&quot;:&quot;5000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;},&quot;ShowLoader&quot;:false,&quot;LoaderColor&quot;:null},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true},{&quot;Id&quot;:3026,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Verifica data de inceput = data sfarsit +1&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4361,&quot;ActionType&quot;:&quot;ShowToastAndContinue&quot;,&quot;Condition&quot;:&quot;0 &amp;amp;&amp;amp; [StatusValidare] == &#39;Data_neconsecutiva&#39;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:2,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:null,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Datele nu sunt consecutive cu ultimul CM.&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;},&quot;BgColor&quot;:null,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;fade&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;5000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;},&quot;ShowLoader&quot;:false,&quot;LoaderColor&quot;:null},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true},{&quot;Id&quot;:3027,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Search Data CM Initial&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4361,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:3,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;;WITH CMBase AS (\n    SELECT\n        Id,\n        LTRIM(RTRIM(ISNULL(Marca, &#39;&#39;))) AS Marca,\n        LTRIM(RTRIM(ISNULL(CodSucursala, &#39;&#39;))) AS CodSucursala,\n        LTRIM(RTRIM(ISNULL(SerieCM, &#39;&#39;))) AS SerieCM,\n        LTRIM(RTRIM(ISNULL(NrCM, &#39;&#39;))) AS NrCM,\n        DatadeInceput,\n        DatadeSfarsit\n    FROM app.ConcediuMedical\n    WHERE LTRIM(RTRIM(ISNULL(Marca, &#39;&#39;))) = LTRIM(RTRIM(ISNULL(@Marca, &#39;&#39;)))\n      AND LTRIM(RTRIM(ISNULL(CodSucursala, &#39;&#39;))) = LTRIM(RTRIM(ISNULL(@CodSucursala, &#39;&#39;)))\n      AND DatadeInceput IS NOT NULL\n      AND DatadeSfarsit IS NOT NULL\n),\nLantCM AS (\n    SELECT\n        Id,\n        SerieCM,\n        NrCM,\n        DatadeInceput,\n        DatadeSfarsit,\n        1 AS Nivel\n    FROM CMBase\n    WHERE DatadeSfarsit = DATEADD(day, -1, TRY_CONVERT(date, @DatadeInceput, 101))\n\n    UNION ALL\n\n    SELECT\n        p.Id,\n        p.SerieCM,\n        p.NrCM,\n        p.DatadeInceput,\n        p.DatadeSfarsit,\n        l.Nivel + 1 AS Nivel\n    FROM CMBase p\n    INNER JOIN LantCM l\n        ON p.DatadeSfarsit = DATEADD(day, -1, l.DatadeInceput)\n)\nSELECT TOP 1\n    CONVERT(nvarchar(10), DatadeInceput, 101) AS DataCMInitial\nFROM LantCM\nWHERE SerieCM = LTRIM(RTRIM(ISNULL(@SerieCM, &#39;&#39;)))\n  AND NrCM = LTRIM(RTRIM(ISNULL(@NrCM, &#39;&#39;)))\nORDER BY DatadeInceput DESC\nOPTION (MAXRECURSION 100);&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[p_Marca]&quot;,&quot;name&quot;:&quot;Marca&quot;},{&quot;value&quot;:&quot;[p_CodSucursala]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[p_NrCMInitial]&quot;,&quot;name&quot;:&quot;NrCM&quot;},{&quot;value&quot;:&quot;[p_SerieCMInitial]&quot;,&quot;name&quot;:&quot;SerieCM&quot;},{&quot;value&quot;:&quot;[p_DatadeInceput]&quot;,&quot;name&quot;:&quot;DatadeInceput&quot;}],&quot;OutputTokenName&quot;:&quot;DataCMInitial&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true},{&quot;Id&quot;:3028,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Set Data CM Initial&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4361,&quot;ActionType&quot;:&quot;ApplyTokens&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:4,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Tokens&quot;:[{&quot;value&quot;:&quot;[DataCMInitial]&quot;,&quot;name&quot;:&quot;p_DataCMInitial&quot;}],&quot;TokenizeTokenNames&quot;:false,&quot;RecursionCount&quot;:&quot;1&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
